#' Cluster analysis
#'
#' Groups samples by hierarchical clustering of dissimilarities calculated
#' with vegan::vegdist and stats::hclust. The dendrogram and optional cluster
#' memberships are descriptive.
#' @section References:
#' Oksanen et al. (2026). vegan: Community Ecology Package (R package version 2.7-5). https://vegandevs.github.io/vegan/
#'
#' @param data .
#' @param vars .
#' @param labels .
#' @param transform .
#' @param distance .
#' @param sampleLabels .
#' @param showLabels Compatibility value for analyses saved before sample
#'   label modes were introduced.
#' @param defineClusters .
#' @param cutMode .
#' @param numberClusters .
#' @param cutHeight .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$warnings} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dendrogramDescription} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dendrogram} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$dendrogramStructure} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membership} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$dendrogramStructure$asDF}
#'
#' \code{as.data.frame(results$dendrogramStructure)}
#'
#' @export
cluster <- function(
    data,
    vars,
    labels = NULL,
    transform = "none",
    distance = "bray",
    sampleLabels = "auto",
    showLabels = "__miso_unset__",
    defineClusters = FALSE,
    cutMode = "number",
    numberClusters = 3,
    cutHeight = 0.5) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("cluster requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(labels)) labels <- jmvcore::resolveQuo(jmvcore::enquo(labels))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(labels), labels, NULL))


    options <- clusterOptions$new(
        vars = vars,
        labels = labels,
        transform = transform,
        distance = distance,
        sampleLabels = sampleLabels,
        showLabels = showLabels,
        defineClusters = defineClusters,
        cutMode = cutMode,
        numberClusters = numberClusters,
        cutHeight = cutHeight)

    analysis <- clusterClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}
